"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Hollow Man', 'author': 'Signature original', 'genre': 'Monster Hunts', 'chapters': [{'n': 1, 'title': 'Move-In', 'text': "the medium Madame Zara helped carry boxes and didn't stay for dinner. 'Call me,' the medium Madame Zara said, 'if the walls start talking.' It was a joke. Tom Riley laughed. The house didn't.\n\nThe first night, Tom Riley found a phone that rings with no line. It wasn't in any box. It was waiting — on the mantel, in the nursery, at the foot of the bed, depending on which telling you believe. This telling says: the mantel.\n\nTom Riley got the keys to Hollow Hill Sanitarium on a Tuesday, in fog so thick the house was a rumor until the door opened. It smelled of dust and old winters. It felt — Tom Riley would later swear — like being watched by something patient."}, {'n': 2, 'title': 'Escalation', 'text': "Tom Riley researched. The archives gave up their dead reluctantly: a death in Hollow Hill Sanitarium, then another, then the silence that means everyone agreed not to speak. a phone that rings with no line appeared in every account, patient as a spider.\n\nThat night Tom Riley dreamed of Hollow Hill Sanitarium as it was: bright, laughing, alive — and of the moment it ended, the scream cut short, the a phone that rings with no line falling. Tom Riley woke knowing two things: what the Hollow Man wanted, and that it wanted Tom Riley next.\n\nThe medium, Madame Zara, came at the medium Madame Zara's begging and left within the hour, pale. 'It isn't a ghost,' she said at the door. 'the Hollow Man never died. That's the problem. It just waited.'"}, {'n': 3, 'title': 'The Pattern', 'text': "The nursery door, locked for decades, opened for Tom Riley like it had been waiting. Inside: dust, a small bed, and a phone that rings with no line's twin — the other half of whatever had been broken that terrible night.\n\nthe medium Madame Zara brought salt, iron, sage — the whole apotropaic grocery list. Tom Riley brought a camera, a recorder, and the stubbornness that had gotten them this far. 'We document,' Tom Riley said. 'Then we end it.'\n\nThe whispers became a voice. It knew Tom Riley's name. It offered a deal: leave Hollow Hill Sanitarium, leave a phone that rings with no line, and walk away clean. Tom Riley considered it for exactly as long as it took to be afraid — then refused."}, {'n': 4, 'title': 'The Night', 'text': "Tom Riley understood then what had to be done: not destroy a phone that rings with no line, but complete it. Join the halves. Speak the name. Give the Hollow Man what it had wanted all along — to be seen, to be mourned, to be released.\n\nthe medium Madame Zara arrived — of course the medium Madame Zara did, called by the thing friends are — with headlights and a crowbar and no plan at all. Together they forced the Hollow Man back toward the nursery, toward a phone that rings with no line, toward the broken place.\n\nWhat followed wasn't a fight; it was a siege of the soul. the Hollow Man wore the faces of everyone Tom Riley loved, starting with the medium Madame Zara, begging to be let in, to be believed, to be obeyed. Tom Riley held the line with the oldest weapon: names, spoken true."}, {'n': 5, 'title': 'Aftermath', 'text': "a phone that rings with no line, mended, sits on the mantel. It doesn't play, or fill, or show. It's just an object now — which is to say, it's just a story. Tom Riley keeps it to remember: fear is a liar, face it.\n\nThe archives got a new entry, in Tom Riley's handwriting: what happened, what worked, what it cost. Let the next tenant know. Let no one ever pretend again.\n\nMadame Zara sent a note: 'You did what I couldn't. The house is clean.' Tom Riley framed it. Not from pride — from proof. Proof that the dark can be answered."}, {'n': 6, 'title': 'Epilogue: The Light Kept', 'text': "the medium Madame Zara visits every anniversary with pancakes and bad jokes. They don't talk about that night. They don't need to. It's in the walls — but the walls, now, are just walls.\n\nYears later, Tom Riley still walks Hollow Hill Sanitarium at night, checking the rooms the way you check on sleeping children. The nursery is a study now. The cold spot is just a draft. Mostly.\n\nfear is a liar, face it — Tom Riley wrote it on the first page of the archive, and on the last. Whoever comes next will read it. Whoever comes next will know."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

